def _python_test_symbol_names(source: Any) -> frozenset[str]:
    """Extract exact Python test function identities without executing code."""

    if not isinstance(source, str):
        return frozenset()
    try:
        tree = ast.parse(source)
    except (SyntaxError, TypeError, ValueError):
        return frozenset()
    return frozenset(
        node.name
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name.startswith("test")
    )


def _canonical_json_text_size(value: str) -> int | None:
    """Return serialized size, including JSON escaping, or None if invalid."""

    try:
        return len(canonical_json(value).encode("utf-8", errors="strict"))
    except (TypeError, UnicodeEncodeError, ValueError):
        return None


def _removed_baseline_test_symbol_projection(
    candidate_diff: Sequence[Any],
) -> dict[str, Any]:
    """Project exact removed Python test identities with deterministic bounds."""

    symbols_by_path: dict[str, set[str]] = {}
    for entry in candidate_diff:
        path = str(getattr(entry, "path", "") or "").strip()
        before_source = getattr(entry, "before_source", None)
        after_source = getattr(entry, "after_source", None)
        if (
            not path
            or not isinstance(before_source, str)
            or not isinstance(after_source, str)
        ):
            continue
        removed = (
            _python_test_symbol_names(before_source)
            - _python_test_symbol_names(after_source)
        )
        if removed:
            symbols_by_path.setdefault(path, set()).update(removed)

    records: list[dict[str, Any]] = []
    remaining_symbol_budget = MAX_PERSISTED_PROPOSAL_REPAIR_SYMBOLS
    for path in sorted(symbols_by_path):
        if len(records) >= MAX_PERSISTED_PROPOSAL_REPAIR_PATHS:
            break
        path_size = _canonical_json_text_size(path)
        if (
            path_size is None
            or path_size > MAX_PERSISTED_PROPOSAL_REPAIR_PATH_JSON_BYTES
        ):
            continue
        removed = tuple(sorted(symbols_by_path[path]))
        included: list[str] = []
        for symbol in removed:
            if remaining_symbol_budget <= 0:
                break
            if SECRET_SHAPED_TEST_SYMBOL_RE.search(symbol):
                continue
            symbol_size = _canonical_json_text_size(symbol)
            if (
                symbol_size is None
                or symbol_size
                > MAX_PERSISTED_PROPOSAL_REPAIR_SYMBOL_JSON_BYTES
            ):
                continue
            included.append(symbol)
            remaining_symbol_budget -= 1
        records.append(
            {
                "path": path,
                "missing_baseline_test_symbols": included,
                "missing_baseline_test_symbol_count": len(removed),
                "missing_baseline_test_symbols_truncated": (
                    len(included) != len(removed)
                ),
            }
        )
    return {
        "records": records,
        "path_count": len(symbols_by_path),
        "paths_truncated": len(records) != len(symbols_by_path),
    }


def implementation_task_claim_protected_fence_paths(
    metadata: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return durable protected-path fences referenced by a task claim.

    A task process can die after persisting its active snapshot or incident.
    The repo-wide claim remains the durable pointer from maintenance to that
    lane-local fence. Filesystem uncertainty is treated as present so shared
    checkout maintenance fails closed.
    """

    state_dir_text = str(metadata.get("state_dir") or "").strip()
    if not state_dir_text:
        return ()
    state_dir = Path(state_dir_text)
    present: list[str] = []
    for filename in (
        IMPLEMENTATION_PROTECTED_ACTIVE_SNAPSHOT_FILENAME,
        IMPLEMENTATION_PROTECTED_INCIDENT_FILENAME,
    ):
        path = state_dir / filename
        try:
            path.lstat()
        except FileNotFoundError:
            continue
        except (OSError, ValueError):
            # An unreadable fence cannot safely be treated as absent.
            pass
        present.append(str(path))
    return tuple(present)


class CrashFenceReconciler:
    """Serialize crash-fence absence proofs with scans outside the exclusive lease.

    Protocol:
    1. If repository-global maintenance is active and a fence exists, defer
       without inspecting or clearing the snapshot/incident.
    2. Scan immutable fence inputs and protected-path identities outside any
       exclusive critical section.
    3. Enter a short :class:`CheckoutMaintenanceLease` only to revalidate those
       inputs and apply a fenced mutation (clear or latch).
    """

    def __init__(
        self,
        daemon: "PortalImplementationDaemon",
        *,
        max_hold_seconds: float = DEFAULT_CHECKOUT_MAINTENANCE_MAX_HOLD_SECONDS,
    ) -> None:
        self._daemon = daemon
        self.max_hold_seconds = float(max_hold_seconds)

    def reconcile(self) -> dict[str, Any]:
        daemon = self._daemon
        incident_path = daemon._implementation_protected_incident_path()
        active_path = daemon._implementation_protected_active_snapshot_path()
        fence_present = False
        try:
            fence_present = incident_path.exists() or active_path.exists()
        except OSError:
            fence_present = True

        maintenance_claim = daemon._active_protected_path_maintenance_claim()
        if maintenance_claim is not None and fence_present:
            result = {
                "blocked": True,
                "deferred": True,
                "reason": "crash_reconciliation_deferred_maintenance_active",
                "maintenance_owner_pid": int(maintenance_claim.get("pid") or 0),
                "maintenance_owner_state_dir": str(
                    maintenance_claim.get("state_dir") or ""
                ),
                "scan_outside_lease": True,
                "critical_section_entered": False,
            }
            daemon._record_event(
                "implementation_protected_path_reconciliation_deferred",
                result,
            )
            return result

        # Phase 1: expensive inspection stays outside the exclusive lease.
        plan = self._scan_outside_lease(
            incident_path=incident_path,
            active_path=active_path,
        )
        if plan.get("action") in {None, "return"}:
            result = dict(plan.get("result") or {"blocked": False, "reason": "no_active_snapshot"})
            result.setdefault("scan_outside_lease", True)
            result.setdefault("critical_section_entered", False)
            return result

        # Phase 2: short exclusive critical section with revalidation.
        lease = CheckoutMaintenanceLease(
            crash_fence_reconciliation_lock_path(daemon.repo_root),
            metadata={
                "kind": "crash-fence-reconciliation",
                "lease_role": "crash_fence_reconciler",
                "repo_root": str(daemon.repo_root.resolve()),
                "state_dir": str(daemon.state_path.parent.resolve()),
                "pid": os.getpid(),
                "owner_script": Path(sys.argv[0]).name,
            },
            max_hold_seconds=self.max_hold_seconds,
        )
        try:
            with lease.exclusive_section(
                owner_is_active=lambda metadata: daemon._lock_owner_is_active(
                    dict(metadata),
                    expected_kind="crash-fence-reconciliation",
                )
            ) as timing:
                result = self._apply_under_lease(
                    plan,
                    incident_path=incident_path,
                    active_path=active_path,
                )
            # Timing is finalized in exclusive_section's finally; attach the
            # completed proof without changing historical top-level keys.
            proof = {
                "scan_outside_lease": True,
                "critical_section_entered": True,
                "critical_section": dict(timing),
                "lease_hold_bounded": bool(timing.get("within_bound")),
                "max_hold_seconds": float(
                    timing.get("max_hold_seconds") or self.max_hold_seconds
                ),
            }
            result["reconciliation_proof"] = proof
            return result
        except RuntimeError as exc:
            reason = str(exc)
            if reason in {
                "checkout_maintenance_lease_active",
                "checkout_maintenance_lease_unavailable",
                "checkout_maintenance_lease_malformed",
                "checkout_maintenance_lease_cleanup_failed",
            } or reason.startswith("checkout maintenance lease hold exceeded"):
                result = {
                    "blocked": True,
                    "deferred": True,
                    "reason": "crash_reconciliation_serialized",
                    "lease_reason": reason,
                    "scan_outside_lease": True,
                    "critical_section_entered": False,
                }
                daemon._record_event(
                    "implementation_protected_path_reconciliation_serialized",
                    result,
                )
                return result
            raise

    def _scan_outside_lease(
        self,
        *,
        incident_path: Path,
        active_path: Path,
    ) -> dict[str, Any]:
        daemon = self._daemon
        input_generations = {
            "incident": durable_input_generation(incident_path),
            "active_snapshot": durable_input_generation(active_path),
        }

        if incident_path.exists():
            incident = load_json_dict(incident_path)
            if isinstance(incident, Mapping):
                auto_plan = daemon._plan_auto_clear_ephemeral_protected_path_deletions(
                    incident
                )
                if auto_plan is not None:
                    return {
                        "action": "auto_clear",
                        "input_generations": input_generations,
                        "auto_plan": auto_plan,
                        "incident": dict(incident),
                    }
            result = {
                "blocked": True,
                "reason": "implementation_protected_path_incident_latched",
                "incident_path": str(incident_path),
                "incident": incident or {"state": "malformed"},
            }
            daemon._record_event(
                "implementation_protected_path_incident_blocked",
                result,
            )
            return {"action": "return", "result": result}

        if not active_path.exists():
            return {
                "action": "return",
                "result": {"blocked": False, "reason": "no_active_snapshot"},
            }

        active = load_json_dict(active_path)
        if active is None:
            return {
                "action": "latch_malformed",
                "input_generations": input_generations,
                "payload": {
                    "reason": "implementation_protected_path_snapshot_malformed",
                    "active_snapshot_path": str(active_path),
                },
            }

        task_id = str(active.get("task_id") or "")
        try:
            attempt = int(active.get("attempt") or 0)
        except (TypeError, ValueError):
            attempt = 0
        workspace_value = str(active.get("workspace_path") or "")
        snapshot = active.get("snapshot")
        missing_ephemeral_workspace = False
        try:
            workspace_path = Path(workspace_value).resolve(strict=False)
            workspace_exists = workspace_path.exists()
            missing_ephemeral_workspace = bool(
                active.get("ephemeral_worktree") is True
                and not workspace_exists
                and isinstance(snapshot, Mapping)
                and daemon._missing_ephemeral_workspace_shared_snapshot(
                    workspace_path,
                    snapshot,
                )
                is not None
            )
            workspace_allowed = (
                workspace_exists or missing_ephemeral_workspace
            ) and (
                workspace_path == daemon.repo_root.resolve()
                or daemon._path_is_under(
                    workspace_path, daemon.worktree_root.resolve()
                )
            )
        except (OSError, RuntimeError):
            workspace_path = Path(workspace_value or ".")
            workspace_allowed = False
        if (
            not task_id
            or attempt <= 0
            or not workspace_allowed
            or not isinstance(snapshot, Mapping)
        ):
            return {
                "action": "latch_invalid",
                "input_generations": input_generations,
                "payload": {
                    "reason": "implementation_protected_path_snapshot_invalid",
                    "task_id": task_id,
                    "attempt": attempt,
                    "workspace_path": workspace_value,
                    "active_snapshot_path": str(active_path),
                },
            }

        # Expensive protected-path scan remains outside the exclusive lease.
        current_snapshot = daemon._implementation_protected_path_snapshot(
            workspace_path
        )
        if daemon._implementation_protected_snapshot_device_renumbered(
            snapshot,
            current_snapshot,
        ):
            return {
                "action": "clear_device_renumbered",
                "input_generations": input_generations,
                "task_id": task_id,
                "attempt": attempt,
                "workspace_path": str(workspace_path),
            }

        # Missing ephemeral workspaces re-root comparison onto the shared
        # checkout; scan that root here so the exclusive section never does.
        violation_after: Mapping[str, Mapping[str, Any]] | None = current_snapshot
        if missing_ephemeral_workspace:
            violation_after = daemon._implementation_protected_path_snapshot(
                daemon.repo_root
            )
        violation = daemon._implementation_protected_path_violation(
            task_id=task_id,
            attempt=attempt,
            workspace_path=workspace_path,
            before=snapshot,
            after=violation_after,
            latch=False,
        )
        if violation:
            return {
                "action": "latch_violation",
                "input_generations": input_generations,
                "payload": violation,
            }

        reconciliation_reason = (
            "crash_reconciliation_ephemeral_workspace_missing"
            if missing_ephemeral_workspace
            else "crash_reconciliation_unchanged"
        )
        return {
            "action": "clear_unchanged",
            "input_generations": input_generations,
            "task_id": task_id,
            "attempt": attempt,
            "workspace_path": str(workspace_path),
            "reason": reconciliation_reason,
        }

    def _revalidate_inputs(
        self,
        *,
        plan: Mapping[str, Any],
        incident_path: Path,
        active_path: Path,
    ) -> dict[str, Any] | None:
        """Return a deferred result when immutable scan inputs drifted."""

        daemon = self._daemon
        maintenance_claim = daemon._active_protected_path_maintenance_claim()
        if maintenance_claim is not None:
            return {
                "blocked": True,
                "deferred": True,
                "reason": "crash_reconciliation_deferred_maintenance_active",
                "maintenance_owner_pid": int(maintenance_claim.get("pid") or 0),
                "maintenance_owner_state_dir": str(
                    maintenance_claim.get("state_dir") or ""
                ),
                "scan_outside_lease": True,
                "critical_section_entered": True,
                "revalidation": "maintenance_became_active",
            }
        expected = plan.get("input_generations")
        if not isinstance(expected, Mapping):
            return {
                "blocked": True,
                "deferred": True,
                "reason": "crash_reconciliation_input_generation_missing",
                "scan_outside_lease": True,
                "critical_section_entered": True,
            }
        observed = {
            "incident": durable_input_generation(incident_path),
            "active_snapshot": durable_input_generation(active_path),
        }
        if not generations_match(
            expected.get("incident"), observed["incident"]
        ) or not generations_match(
            expected.get("active_snapshot"), observed["active_snapshot"]
        ):
            return {
                "blocked": True,
                "deferred": True,
                "reason": "crash_reconciliation_input_changed",
                "scan_outside_lease": True,
                "critical_section_entered": True,
                "expected_generations": dict(expected),
                "observed_generations": observed,
            }
        return None

    def _apply_under_lease(
        self,
        plan: Mapping[str, Any],
        *,
        incident_path: Path,
        active_path: Path,
    ) -> dict[str, Any]:
        daemon = self._daemon
        deferred = self._revalidate_inputs(
            plan=plan,
            incident_path=incident_path,
            active_path=active_path,
        )
        if deferred is not None:
            return dict(deferred)

        action = str(plan.get("action") or "")
        if action == "auto_clear":
            auto_plan = plan.get("auto_plan")
            if not isinstance(auto_plan, Mapping):
                return {
                    "blocked": True,
                    "reason": "implementation_protected_path_incident_latched",
                    "incident_path": str(incident_path),
                }
            return daemon._apply_auto_clear_protected_path_plan(
                auto_plan,
                incident_path=incident_path,
                active_path=active_path,
            )
        if action == "latch_malformed":
            payload = dict(plan.get("payload") or {})
            incident = daemon._latch_implementation_protected_incident(payload)
            daemon._record_event(
                "implementation_protected_path_snapshot_malformed",
                incident,
            )
            return {
                "blocked": True,
                "reason": "implementation_protected_path_snapshot_malformed",
                "incident": incident,
            }
        if action == "latch_invalid":
            payload = dict(plan.get("payload") or {})
            incident = daemon._latch_implementation_protected_incident(payload)
            daemon._record_event(
                "implementation_protected_path_snapshot_invalid",
                incident,
            )
            return {
                "blocked": True,
                "reason": "implementation_protected_path_snapshot_invalid",
                "incident": incident,
            }
        if action == "latch_violation":
            payload = dict(plan.get("payload") or {})
            incident = daemon._latch_implementation_protected_incident(payload)
            daemon._record_event(
                "implementation_protected_path_mutated",
                payload,
            )
            return {
                "blocked": True,
                "reason": "implementation_protected_path_mutated",
                "incident": incident,
            }
        if action == "clear_device_renumbered":
            task_id = str(plan.get("task_id") or "")
            try:
                attempt = int(plan.get("attempt") or 0)
            except (TypeError, ValueError):
                attempt = 0
            daemon._clear_implementation_protected_snapshot(
                task_id=task_id,
                attempt=attempt,
                reason="crash_reconciliation_device_renumbered",
            )
            result = {
                "blocked": False,
                "reason": "crash_reconciliation_device_renumbered",
                "task_id": task_id,
                "attempt": attempt,
            }
            daemon._record_event(
                "implementation_protected_path_snapshot_reconciled",
                result,
            )
            return result
        if action == "clear_unchanged":
            task_id = str(plan.get("task_id") or "")
            try:
                attempt = int(plan.get("attempt") or 0)
            except (TypeError, ValueError):
                attempt = 0
            reason = str(plan.get("reason") or "crash_reconciliation_unchanged")
            daemon._clear_implementation_protected_snapshot(
                task_id=task_id,
                attempt=attempt,
                reason=reason,
            )
            result = {
                "blocked": False,
                "reason": reason,
                "task_id": task_id,
                "attempt": attempt,
                "workspace_path": str(plan.get("workspace_path") or ""),
            }
            daemon._record_event(
                "implementation_protected_path_snapshot_reconciled",
                result,
            )
            return result
        return {
            "blocked": True,
            "reason": "crash_reconciliation_unknown_action",
            "action": action,
        }


EVENT_DRIVEN_RUNTIME_REQUIREMENT_ID = (
    "asi-117:event-driven-delta-checkpoint-runtime"
)

RUNTIME_CHECKPOINT_SCHEMA = (
    "ipfs_accelerate_py.agent_supervisor.event-driven-runtime-checkpoint@1"
)
RUNTIME_WAKE_KINDS = frozenset(
    {
        "task_board",
        "objective",
        "repository",
        "child_process",
        "lease",
        "validation",
        "provider_capacity",
        "policy",
        "observation_window",
    }
)
DEFAULT_MISSED_NOTIFICATION_RECONCILIATION_SECONDS = 3600.0


def default_llm_merge_resolver_command() -> str:
    """Return the configured resolver or the packaged agent fallback.

    The fallback starts Codex in the conflicted workspace and uses Copilot only
    when Codex cannot complete the repair. Keeping this as the daemon default
    means semantic merge conflicts are actively repaired instead of merely
    recorded for a later manual retry.
    """

    configured = os.environ.get(LLM_MERGE_RESOLVER_COMMAND_ENV, "").strip()
    if configured:
        return configured
    return llm_merge_resolver_fallback_command(python_executable=sys.executable)


def _env_int(name: str, default: int) -> int:
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    try:
        return int(raw)
    except ValueError:
        return default


def _env_nonnegative_int(name: str, default: int) -> int:
    value = _env_int(name, default)
    return value if value >= 0 else default


def _env_float(name: str, default: float) -> float:
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    try:
        return float(raw)
    except ValueError:
        return default


def _env_bool(name: str, default: bool) -> bool:
    raw = os.environ.get(name, "").strip().lower()
    if not raw:
        return default
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    return default


def _bounded_merge_proof_value(
    value: Any,
    *,
    depth: int = 0,
    field_name: str = "",
) -> Any:
    """Project proof metadata without persisting raw outputs or witnesses.

    Merge queue records are long-lived coordination artifacts, not proof
    artifact storage.  Preserve the bounded identities and verdicts needed to
    reproduce a gate decision while leaving potentially large or sensitive
    provider material in its dedicated artifact store.
    """

    if depth >= MAX_MERGE_PROOF_METADATA_DEPTH:
        return None
    normalized_name = str(field_name or "").strip().lower().replace("-", "_")
    if (
        normalized_name in {
            "output",
            "outputs",
            "stdout",
            "stderr",
            "witness",
            "witnesses",
            "counterexample",
            "counterexamples",
            "prompt",
            "prompts",
            "model_output",
            "provider_response",
            "proof_blob",
            "proof_bytes",
            "proof_text",
            "raw_context",
            "raw_output",
            "raw_response",
        }
        or normalized_name.endswith("_witness")
        or normalized_name.endswith("_output")
    ):
        return None
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        return value[:MAX_MERGE_PROOF_METADATA_TEXT]
    enum_value = getattr(value, "value", None)
    if isinstance(enum_value, (str, int, float, bool)):
        return _bounded_merge_proof_value(
            enum_value,
            depth=depth + 1,
            field_name=field_name,
        )
    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        try:
            value = to_dict()
        except (TypeError, ValueError):
            return None
    if isinstance(value, Mapping):
        projected: dict[str, Any] = {}
        for raw_key in sorted(value, key=lambda item: str(item))[
            :MAX_MERGE_PROOF_METADATA_ITEMS
        ]:
            key = str(raw_key)[:MAX_MERGE_PROOF_METADATA_TEXT]
            projected_value = _bounded_merge_proof_value(
                value[raw_key],
                depth=depth + 1,
                field_name=key,
            )
            if projected_value is not None:
                projected[key] = projected_value
        return projected
    if isinstance(value, Sequence) and not isinstance(
        value, (str, bytes, bytearray)
    ):
        projected_items = []
        for item in value[:MAX_MERGE_PROOF_METADATA_ITEMS]:
            projected_item = _bounded_merge_proof_value(
                item,
                depth=depth + 1,
                field_name=field_name,
            )
            if projected_item is not None:
                projected_items.append(projected_item)
        return projected_items
    return str(value)[:MAX_MERGE_PROOF_METADATA_TEXT]


def _canonical_receipt_value(value: Any) -> Any:
    """Project runtime evidence into the canonical proof value domain."""

    if isinstance(value, float):
        return format(value, ".17g")
    if isinstance(value, Mapping):
        return {
            str(key): _canonical_receipt_value(item)
            for key, item in value.items()
        }
    if isinstance(value, Sequence) and not isinstance(
        value,
        (str, bytes, bytearray),
    ):
        return [_canonical_receipt_value(item) for item in value]
    if value is None or isinstance(value, (str, bool, int)):
        return value
    return str(value)


def shared_worktree_source_roots(repo_root: Path) -> tuple[Path, ...]:
    """Return checkout roots that may provide untracked shared dependencies.

    An ephemeral worktree normally links dependencies from ``repo_root``. A
    branch checkout can omit untracked directories such as
    ``swissknife/node_modules`` though, so an operator may configure a stable
    checkout containing those installed dependencies. Multiple roots use the
    platform path separator.
    """

    candidates = [repo_root]
    configured = os.environ.get(SHARED_WORKTREE_SOURCE_ROOT_ENV, "")
    for raw_root in configured.split(os.pathsep):
        value = raw_root.strip()
        if not value:
            continue
        candidate = Path(value).expanduser()
        if not candidate.is_absolute():
            candidate = repo_root / candidate
        candidates.append(candidate)

    roots: list[Path] = []
    for candidate in candidates:
        try:
            resolved = candidate.resolve(strict=True)
        except (OSError, RuntimeError):
            continue
        if resolved.is_dir() and resolved not in roots:
            roots.append(resolved)
    return tuple(roots)


def normalize_relative_path_list(values: Any) -> tuple[str, ...]:
    """Normalize comma/list configured repo-relative paths."""

    if values is None:
        raw_values: list[Any] = []
    elif isinstance(values, str):
        raw_values = [values]
    else:
        raw_values = list(values)

    paths: list[str] = []
    for value in raw_values:
        for raw_path in str(value).split(","):
            path = raw_path.strip().strip("/")
            if not path or path.startswith("/") or "\0" in path:
                continue
            if ".." in Path(path).parts:
                continue
            if path not in paths:
                paths.append(path)
    return tuple(paths)


def normalize_implementation_protected_paths(
    values: Any,
    *,
    repo_root: Path | None = None,
) -> tuple[str, ...]:
    """Return validated exact repo-relative files protected from implementation.

    Unlike the permissive submodule-path normalizer, this operator security
    boundary rejects the complete configuration when any non-empty entry is
    unsafe.  Paths may be supplied repeatedly or comma-separated.  Existing
    directories, absolute paths, traversal, platform-specific aliases, and
    symlink escapes are not valid exact-file declarations.
    """

    if values is None:
        raw_values: list[Any] = []
    elif isinstance(values, str):
        raw_values = [values]
    else:
        raw_values = list(values)

    root = repo_root.resolve() if repo_root is not None else None
    protected: list[str] = []
    for value in raw_values:
        for raw_path in str(value).split(","):
            relative = raw_path.strip()
            if not relative:
                continue
            candidate_path = Path(relative)
            if (
                relative in {".", ".."}
                or relative.startswith(("/", "\\"))
                or relative.endswith(("/", "\\"))
                or "\\" in relative
                or "\0" in relative
                or "://" in relative
                or re.match(r"^[A-Za-z]:", relative)
                or candidate_path.is_absolute()
                or ".." in candidate_path.parts
            ):
                raise ValueError(
                    "implementation protected paths must be safe exact "
                    f"repo-relative files: {relative!r}"
                )
            normalized = candidate_path.as_posix()
            if normalized in {"", "."}:
                raise ValueError(
                    "implementation protected paths must name an exact file"
                )
            if root is not None:
                unresolved = root / normalized
                if unresolved.is_symlink():
                    raise ValueError(
                        "implementation protected paths must not be symlinks: "
                        f"{relative!r}"
                    )
                try:
                    resolved = unresolved.resolve(strict=False)
                    resolved.relative_to(root)
                except (OSError, RuntimeError, ValueError) as exc:
                    raise ValueError(
                        "implementation protected path escapes the repository: "
                        f"{relative!r}"
                    ) from exc
                if resolved.exists() and resolved.is_dir():
                    raise ValueError(
                        "implementation protected paths must name exact files, "
                        f"not directories: {relative!r}"
                    )
            if normalized not in protected:
                protected.append(normalized)
    return tuple(protected)


def normalize_focus_tracks(values: Any) -> list[str]:
    """Normalize scheduler focus tracks while keeping launch-readiness first."""

    if values is None:
        raw_values: list[Any] = list(DEFAULT_TRACKS)
    elif isinstance(values, str):
        raw_values = values.split(",")
    else:
        try:
            raw_values = list(values)
        except TypeError:
            raw_values = [values]

    configured = [str(item).strip().lower() for item in raw_values if str(item).strip()]
    return list(dict.fromkeys(["launch", *configured, *DEFAULT_TRACKS]))


